<template>
  <base-layout>
    <v-toolbar v-if="authenticated" flat color="grey lighten-3" height="40">
      <v-toolbar-title class="subheading">Data WIP</v-toolbar-title>
    </v-toolbar>
    <div>
      <div>
        <v-card flat class="pa-3 table-sm table-striped">
          <v-form ref="form">
            <v-layout row wrap>
              <v-flex xs2 class="px-2">
                <select-view
                  placeholder="Periode"
                  v-model="filterInputTmp.periode"
                  from-file="periode"
                  name="Periode"
                  searchable
                  v-validate="'required'"
                  :error-messages="errors.collect('Periode')"
                ></select-view>
              </v-flex>
              <v-flex xs3 class="px-2">
                <select-view
                  placeholder="Tipe Mutasi"
                  v-model="filterInputTmp.tipeMutasi"
                  from-file="grouptype"
                  name="Tipe Mutasi"
                  searchable
                  v-validate="'required'"
                  :error-messages="errors.collect('Tipe Mutasi')"
                  :on-selected="onSelectedTipeMutasi"
                  :extra-query-options="groupTypeQueryOptions"
                ></select-view>
              </v-flex>
              <v-flex xs5 class="mt-2">
                <v-btn color="primary" @click="submitFilter()">Cari</v-btn>
                <v-btn
                  @click="print()"
                  v-if="state.isSubmitted && data.length > 0"
                  success
                  dark
                  class="blue-grey white--text"
                >Buat Laporan</v-btn>
                <v-btn
                  @click="download()"
                  v-if="state.isSubmitted && data.length > 0"
                  success
                  dark
                  class="green white--text"
                >Export Excel</v-btn>
              </v-flex>
              <v-flex xs2>
                <v-text-field
                  v-if="filterInput.periode != ''"
                  label="Cari..."
                  append-icon="search"
                  class="mb-2"
                  v-model="searchQuery"
                  hide-details
                ></v-text-field>
              </v-flex>
            </v-layout>
            <!-- <v-divider></v-divider> -->
          </v-form>
          <table-view
            v-show="state.isSubmitted"
            from-file="wip"
            :extra-query-options="dataExtraQueryOptions"
            :is-refresh="state.isRefresh"
            :get-items="(data)=> { this.data = data; }"
            :get-columns="(columns)=> {this.columns = columns;}"
            :response-callback="responseCallback"
          ></table-view>
        </v-card>
      </div>
    </div>
    <query-service
      v-model="settingPrintModel"
      from-file="setting_print"
      :extra-query-options="settingPrintQueryOptions"
    />
  </base-layout>
</template>

<script>
import moment from "moment";
import _debounce from "lodash/debounce";
// import _filter from "lodash/filter";

import { post } from "@/utils/proxy";
import { print, excel } from "@/utils/exportDownload";

import { API_LOCATION } from "@/constants";

export default {
  data() {
    return {
      q: "",
      state: {
        isRefresh: false,
        isSubmitted: false
      },
      filterInput: {
        periode: "",
        tipeMutasi: ""
      },
      filterInputTmp: {
        periode: "",
        tipeMutasi: ""
      },
      data: [],
      columns: [],
      dpDropdown: [],
      settingPrintModel: [],
      base64Header1: "",
      base64Header2: "",
      tipeMutasi: "",
      searchQuery: "",
      groupTypeQueryOptions: {
        name: "wip"
      }
    };
  },
  methods: {
    debounce: _debounce(f => {
      f();
    }, 600),
    responseCallback(data, pagination) {
      const newData = [];
      data.forEach((item, index) => {
        newData.push(
          Object.assign(item, {
            text01: index + ((pagination.page - 1) * pagination.rowsPerPage) + 1
          })
        );
      });
      return newData;
    },
    responseCallbackLaporan(data) {
      const newData = [];
      let i = 1;
      data.forEach(item => {
        newData.push(Object.assign(item, { text01: i }));
        i += 1;
      });
      return newData;
    },
    onSelectedTipeMutasi(data) {
      this.tipeMutasi = data.name.toUpperCase();
    },
    formatCurrency(value) {
      const val = parseFloat(value, 10);
      return val.toFixed(2).replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,");
    },
    submitFilter() {
      this.$validator.validateAll().then(() => {
        if (!this.errors.any()) {
          if (!this.state.isSubmitted) {
            this.state.isSubmitted = true;
          }
          this.filterInput = Object.assign({}, this.filterInputTmp);
        } else {
          $(`[name="${this.errors.items[0].field}"]`).focus();
        }
      });
    },
    download() {
      post("base/table/getData", {
        name: "wip",
        where: {
          AND: this.dataExtraQueryOptions
        }
      }).then(response => {
        excel(
          [
            {
              table: {
                title: `LAPORAN POSISI BARANG DALAM PROSES PERIODE: ${this.labelPeriode}`,
                fields: this.columns.map(item => ({
                  id: item.value,
                  title: item.text
                })),
                data: this.responseCallbackLaporan(response.data)
              }
            }
          ],
          "LAPORAN WIP"
        );
      });
    },
    print() {
      const rotateImages = [
        post(
          `${API_LOCATION}app/getRotateTextImage?text=LAPORAN POSISI BARANG DALAM PROSES&s=22&align=center`
        ),
        post(
          `${API_LOCATION}app/getRotateTextImage?text=PERIODE :     ${this.labelPeriode}&s=20&align=center`
        )
      ];
      post("base/table/getData", {
        name: "wip",
        where: this.dataExtraQueryOptions
      }).then(response => {
        Promise.all(rotateImages).then(images => {
          this.base64Header1 = images[0].base64;
          this.base64Header2 = images[1].base64;
          this.printReport(this.responseCallbackLaporan(response.data));
        });
      });
    },
    printReport(data = []) {
      const writeRotatedText = (text, size) => {
        let ctx = "";
        const canvas = document.createElement("canvas");
        canvas.width = 36;
        canvas.height = 700;
        ctx = canvas.getContext("2d");
        ctx.font = `${size}pt Arial`;
        ctx.save();
        ctx.translate(36, 700);
        ctx.rotate(-0.5 * Math.PI);
        ctx.fillStyle = "#000";
        ctx.fillText(text, 0, 0);
        ctx.restore();
        return canvas.toDataURL();
      };

      const customWidths = [];
      const customBody = [];
      const header1 = [];
      const header2 = [];
      const header3 = [];
      const headerColumns = [];
      this.columns.forEach((item, index) => {
        customWidths.push(parseInt(item.width_print, 10));
        if (index === 0) {
          header1.push({
            text: `LAPORAN POSISI BARANG DALAM PROSES (WIP)`,
            colSpan: this.columns.length + 1,
            style: "f15",
            alignment: "left",
            border: [false, false, false, false]
          });
          header2.push({
            text: `KAWASAN BERIKAT: ${this.appSettings.nama_pt.toUpperCase()}`,
            colSpan: this.columns.length + 1,
            style: "f15",
            alignment: "left",
            border: [false, false, false, false]
          });
          header3.push({
            text: `PERIODE: ${this.labelPeriode}`,
            colSpan: this.columns.length + 1,
            style: ["f15", "mb25"],
            alignment: "left",
            border: [false, false, false, false]
          });
        } else {
          header1.push({});
          header2.push({});
          header3.push({});
        }

        headerColumns.push({
          text: item.text,
          alignment: item.align,
          bold: true
        });
      });
      customWidths.push("*");
      header1.push({});
      header2.push({});
      header3.push({});
      headerColumns.push({
        text: "",
        border: [false, false, false, false]
      });

      customBody.push(header1);
      customBody.push(header2);
      customBody.push(header3);
      customBody.push(headerColumns);

      data.forEach(item => {
        const bodyRows = [];
        this.columns.forEach(col => {
          const row = {
            text: item[col.value],
            alignment: col.align,
            maxHeight: 15
          };
          if (col.type === "date") {
            row.text = moment(item[col.value]).format(col.options.format);
          }
          if (col.type === "currency") {
            row.text = this.formatCurrency(item[col.value]);
          }
          bodyRows.push(row);
        });
        bodyRows.push({
          text: "",
          border: [false, false, false, false]
        });
        customBody.push(bodyRows);
      });

      const exportedData = [
        {
          colGroups: [
            [
              {
                cTable: {
                  widths: [150, 30, 30, 30, 600, 30, 30, 30],
                  heights: [755],
                  body: [
                    [
                      {
                        text: "",
                        border: [false, false, false, false]
                      },
                      {
                        image: this.base64Header1,
                        alignment: "right",
                        border: [false, false, false, false]
                      },
                      {
                        image: this.base64Header2,
                        alignment: "right",
                        border: [false, false, false, false]
                      },
                      {
                        text: "",
                        alignment: "right",
                        border: [false, false, false, false]
                      },
                      {
                        text: "",
                        border: [false, false, false, false]
                      },
                      {
                        image: writeRotatedText(
                          this.appSettings.nama_pt.toUpperCase(),
                          18
                        ),
                        alignment: "right",
                        border: [false, false, false, false]
                      },
                      {
                        image: writeRotatedText(
                          "DELTA SILICON INDUSTRIAL PARK. JL KRUING I BLOCK L5 NO 3A",
                          12
                        ),
                        alignment: "right",
                        border: [false, false, false, false]
                      },
                      {
                        image: writeRotatedText(
                          "LEMAHABANG, BEKASI. 17550",
                          12
                        ),
                        alignment: "right",
                        border: [false, false, false, false]
                      }
                    ]
                  ]
                }
              },
              {
                cTable: {
                  headerRows: 4,
                  widths: customWidths,
                  body: customBody
                }
              },
              {
                cTable: {
                  widths: [800, "*"],
                  body: [
                    [
                      { text: "", border: [false, false, false, false] },
                      {
                        text: "Kami Bertanggung Jawab Atas",
                        alignment: "left",
                        style: ["f11", "mt50"],
                        border: [false, false, false, false]
                      }
                    ],
                    [
                      { text: "", border: [false, false, false, false] },
                      {
                        text: "Kebenaran Laporan Ini",
                        alignment: "left",
                        style: ["f11"],
                        border: [false, false, false, false]
                      }
                    ],
                    [
                      { text: "", border: [false, false, false, false] },
                      {
                        text: `${this.settingPrint.tempat}, ${moment(
                          this.settingPrint.tanggal
                        )
                          .locale("id")
                          .format("DD MMMM YYYY")}`,
                        alignment: "left",
                        style: ["f11", "mb50"],
                        border: [false, false, false, false]
                      }
                    ],
                    [
                      { text: "", border: [false, false, false, false] },
                      {
                        text: this.settingPrint.nama,
                        alignment: "left",
                        style: ["f11"],
                        border: [false, false, false, false]
                      }
                    ],
                    [
                      { text: "", border: [false, false, false, false] },
                      {
                        text: this.settingPrint.jabatan,
                        alignment: "left",
                        style: ["f11"],
                        border: [false, false, false, false]
                      }
                    ]
                  ]
                }
              }
            ]
          ]
        }
      ];
      const fileName = "Laporan WIP";
      print(exportedData, fileName, "landscape", "A3");
    }
  },
  created() {},
  watch: {
    searchQuery() {
      this.debounce(() => {
        this.q = this.searchQuery.trim();
      });
    }
  },
  computed: {
    dataExtraQueryOptions() {
      const extraQueryOptions = {
        AND: {
          TahunBulan: "-1"
        }
      };
      if (
        this.filterInput.periode !== "" &&
        this.filterInput.periode !== null
      ) {
        extraQueryOptions.AND.TahunBulan = this.filterInput.periode;
      }

      if (
        this.filterInput.tipeMutasi !== "" &&
        this.filterInput.tipeMutasi !== null
      ) {
        extraQueryOptions.AND.id_type = this.filterInput.tipeMutasi.split(",");
      }

      if (this.q !== "") {
        extraQueryOptions.AND.OR = {};
        this.columns.forEach(item => {
          extraQueryOptions.AND.OR[`${item.value}[~]`] = this.q;
        });
      }

      return extraQueryOptions;
    },
    appSettings() {
      return this.$store.state.app.appSettings;
    },
    authenticated() {
      return this.$store.state.auth.authenticated;
    },
    user() {
      return this.$store.state.auth.user;
    },
    windowSize() {
      return this.$store.state.app.windowSize;
    },
    labelPeriode() {
      const month = this.filterInput.periode.substring(4);
      const year = this.filterInput.periode.substring(0, 4);
      const label = `01-${month}-${year}    S/D    31-${month}-${year}`;
      return label;
    },
    settingPrintQueryOptions() {
      return [
        {
          periode: this.filterInput.periode,
          jenis: "wip"
        }
      ];
    },
    settingPrint() {
      let data = {};
      if (this.settingPrintModel[0]) {
        if (this.settingPrintModel[0].length > 0) {
          data = this.settingPrintModel[0][0];
        } else {
          data = {
            periode: "",
            tempat: "Bekasi",
            tanggal: new Date(),
            nama: "Dedi Kusnanto",
            jabatan: "Kuasa Direksi"
          };
        }
      }
      return data;
    }
  }
};
</script>
<style scoped>
</style>



